#include <stdio.h>

int main() {
    int a[] = {10, 20, 30, 40, 50, 60};
    int left = 0, right = 5;
    while (left < right) {
        int temp = a[left];
        a[left++] = a[right];
        a[right--] = temp;
    }
    for (int i = 0; i < 6; i++) {
        printf("%d\n", a[i]);
    }
    return 0;
}
